import http from 'node:http';
import https from 'node:https';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {syncBuiltinESMExports} from 'node:module';
const append=fs.appendFileSync.bind(fs),log=process.env.LUMINE_TEXT_GUARD_LOG,work=process.env.LUMINE_TEXT_FIXTURE_WORK;
const boundaries=[work,'/private'+work];
function blocked(api,kind){append(log,JSON.stringify({api,kind,blocked:true})+'\n');throw new Error('TEXT_LIFECYCLE_BLOCKED:'+kind+':'+api);}
function reject(api){return function(){return blocked(api,'network');};}
http.request=reject('http.request');http.get=reject('http.get');https.request=reject('https.request');https.get=reject('https.get');globalThis.fetch=reject('fetch');
function allowed(value){if(typeof value==='number')return true;let p;if(value instanceof URL)p=fileURLToPath(value);else if(typeof value==='string'||Buffer.isBuffer(value))p=String(value);else return true;const absolute=path.resolve(p);return boundaries.some(base=>absolute===base||absolute.startsWith(base+path.sep));}
const operations=['readFileSync','writeFileSync','appendFileSync','readdirSync','statSync','lstatSync','existsSync','realpathSync','openSync','mkdirSync','unlinkSync','rmSync','rmdirSync','renameSync','copyFileSync'];
for(const api of operations){const original=fs[api];if(typeof original!=='function')continue;const wrapped=function(...args){if(!allowed(args[0])||(['renameSync','copyFileSync'].includes(api)&&!allowed(args[1])))return blocked('fs.'+api,'filesystem-boundary');return original.apply(this,args);};if(api==='realpathSync'&&original.native)wrapped.native=function(...args){if(!allowed(args[0]))return blocked('fs.realpathSync.native','filesystem-boundary');return original.native(...args);};fs[api]=wrapped;}
for(const api of ['readFile','writeFile','appendFile','readdir','stat','lstat','realpath','open','mkdir','unlink','rm','rmdir','rename','copyFile']){const original=fs.promises[api];if(typeof original!=='function')continue;fs.promises[api]=async function(...args){if(!allowed(args[0])||(['rename','copyFile'].includes(api)&&!allowed(args[1])))return blocked('fs.promises.'+api,'filesystem-boundary');return original.apply(this,args);};}
syncBuiltinESMExports();

